local Singleton = import 'Frame.Singleton'


---@class MazeLoadScene : Singleton
---@field GetInstance fun(self:MazeLoadScene):MazeLoadScene
local MazeLoadScene = Class("MazeLoadScene", Singleton)



-- ============================================ 

--- lua:
local cs_coroutine = require 'XLua.cs_coroutine' -- 协程
local Yielders = CS.Engine.Lib.Yielders -- 协程


local UIModule = CS.Engine.UI.UIModule
local SDKService = import('Game.Entry.SDKService')
local KTool = CS.Engine.Lib.KTool

local BehaviourAction = CS.Engine.Lib.BehaviourAction

local SceneManagementIns      = SceneManagement:GetInstance()


-- ============================================ 





-- ============================================ 


function MazeLoadScene:__init()
    self.controller = nil
    ---场景实例
    self._sceneIns = nil

    self.isLoadFinished = false

end


function MazeLoadScene:__delete()

    if not isNull(self._sceneIns) then
        CoStart(function()
                cs_coroutine.yield_return(SceneManagementIns:UnloadAppendedScene(self._sceneIns))
        
        end)
        self._sceneIns = nil
    end
end



-- ============================================================================================================


-- sceneId_3D_: string, "37" 这种 
-- sceneId_2D_: string, "39" 这种 
function MazeLoadScene:LoadSceneTo2DMaze( sceneId_3D_, sceneId_2D_ )

    self.isLoadFinished = false

    GameUtils.ShowBlackOverlay(nil, function()

        UIModule.OpenDialog(
            UIArgs(Constants.UITypeIds.MapDecryption2DMazeUI, {}), -- target
            {
                --UIArgs(Constants.UITypeIds.MapDecryptionHomeView)        -- last  春节3D场景 - 主ui
                UIArgs(Constants.UITypeIds.MapDecryptionExploreTracking) -- last  春节3D场景 - 对准桌面的 ui 界面
            }
        )

        SceneManagementIns:SetActive(sceneId_3D_, false)

        self.sceneId_3D = sceneId_3D_

        if isNull(self._sceneIns) then
            --self:LoadScene_()
            cs_coroutine.yield_return(SceneManagementIns:AppendScene(sceneId_2D_, true))
            self._sceneIns = SceneManagementIns:GetSceneInstance(sceneId_2D_)
        else
            SceneManagementIns:SetActive(sceneId_2D_, true)
        end

        self.isLoadFinished = true

    end)
end





function MazeLoadScene:BackTo3DScene()

    self.isLoadFinished = false
    assert( type(self.sceneId_3D) == "string" )

    GameUtils.ShowBlackOverlay(nil, function()

        if not isNull(self._sceneIns) then
            cs_coroutine.yield_return(SceneManagementIns:UnloadAppendedScene(self._sceneIns))
            self._sceneIns = nil
        else
            cs_coroutine.yield_return()
        end
        UIModule.BackDialog()

        SceneManagementIns:SetActive(self.sceneId_3D, true)

        -- 为确保 exploreCamera 一定被 brain 选中, 先关闭它, 然后再打开它

        ---@type MapDecryptionExploreTrackingController
        local controllerComp = MapDecryptionMgr:GetControllerCompByType(MapDecryptionConstants.ControllerCompType.ExploreTracking)
        local SubViewType = MapDecryptionConstants.ExploreTrackingSubViewType

        cs_coroutine.yield_return()
        controllerComp:ShowVirtualCameraBySubType( nil ) -- 将 exploreCamera 关闭
        cs_coroutine.yield_return()
        controllerComp:ShowVirtualCameraBySubType( SubViewType.Explore ) -- 将 exploreCamera 再次开启, 确保它一定是最后一个开启的 vcam 
        cs_coroutine.yield_return()

        cs_coroutine.yield_return(Yielders.GetWaitForSeconds( 0.5 )) -- 有时 vcam 间的切换过程可能会暴露出来, 用此等待来遮盖掉
        --
        self.isLoadFinished = true
        return
    end)
end





return MazeLoadScene